function swapExactEthForToken(
        address tokenOut,
        bytes calldata commands,
        bytes[] calldata inputs,
        uint256 minOut
    ) external payable returns (uint256 out) {
        if (msg.value == 0) revert EthValueMismatch();

        uint256 pre = IERC20(tokenOut).balanceOf(msg.sender);
