function advanceRound(
        uint256 lockRoundId,
        uint256 settleRoundId,
        uint256 nextRoundId,
        bytes[] calldata lockPriceUpdateData,
        bytes[] calldata settlePriceUpdateData,
        bytes[] calldata startPriceUpdateData,
        uint256 lockUpdateFee,
        uint256 settleUpdateFee,
        uint256 startUpdateFee
    ) external payable {
        _enforceSettlementOperator();
        if (
            settleRoundId == 0 ||
            lockRoundId != settleRoundId + 1 ||
            nextRoundId != lockRoundId + 1
        ) {
            revert InvalidRound();
        }

        if (msg.value != lockUpdateFee + settleUpdateFee + startUpdateFee) {
            revert InvalidAmount();
        }

        _lockRound(lockRoundId, lockPriceUpdateData, lockUpdateFee);
        _settleRound(settleRoundId, settlePriceUpdateData, settleUpdateFee);
        _startRound(nextRoundId, startPriceUpdateData, startUpdateFee);
    }

